package perl

import (
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"math"
	"os"
	"strconv"
	"testing"
)

// golden is testdata/golden.json: the results of Perl itself, generated by
// conformance/perl/gen_perl_golden.pl. Floats are given by their bits.
type golden struct {
	NumString []struct {
		Bits string `json:"bits"`
		Out  string `json:"out"`
	} `json:"num_string"`
	Numify []struct {
		In    string `json:"in"`
		Out   string `json:"out"`
		IsInt bool   `json:"is_int"`
		IsUV  bool   `json:"is_uv"`
		LLN   bool   `json:"lln"`
		True  bool   `json:"true"`
	} `json:"numify"`
	Text []struct {
		In        string `json:"in"`
		Lc        string `json:"lc"`
		Substr128 string `json:"substr128"`
		Substr3   string `json:"substr3"`
	} `json:"text"`
	Round []struct {
		Bits  string `json:"bits"`
		Round string `json:"round"`
		Int   string `json:"int"`
	} `json:"round"`
	Fixed []struct {
		Bits string            `json:"bits"`
		Out  map[string]string `json:"out"`
	} `json:"fixed"`
}

func loadGolden(t *testing.T) golden {
	t.Helper()
	data, err := os.ReadFile("testdata/golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var g golden
	if err := json.Unmarshal(data, &g); err != nil {
		t.Fatal(err)
	}
	return g
}

func fromBits(t *testing.T, s string) float64 {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil || len(b) != 8 {
		t.Fatalf("bad bits %q", s)
	}
	return math.Float64frombits(binary.BigEndian.Uint64(b))
}

// TestNumString checks the stringification of floats ("$nv")
func TestNumString(t *testing.T) {
	for _, c := range loadGolden(t).NumString {
		f := fromBits(t, c.Bits)
		if got := NumString(f); got != c.Out {
			t.Errorf("NumString(%v) = %q, Perl %q", f, got, c.Out)
		}
	}
}

// TestNumify checks numeric context (0 + $s), whether the result is an
// integer, looks_like_number and truthiness
func TestNumify(t *testing.T) {
	for _, c := range loadGolden(t).Numify {
		if got := NumString(Numify(c.In)); got != c.Out && !c.IsInt {
			t.Errorf("Numify(%q) = %q, Perl %q", c.In, got, c.Out)
		}
		v, isInt := NumifyTyped(c.In)
		var got string
		if i, ok := v.(int64); ok {
			got = strconv.FormatInt(i, 10)
		} else {
			got = NumString(v.(float64))
		}
		// A UV is a float here (see NumifyTyped)
		if c.IsUV {
			if isInt || got != NumString(Numify(c.In)) {
				t.Errorf("NumifyTyped(%q) = %q (integer %v), want a float", c.In, got, isInt)
			}
			continue
		}
		if got != c.Out || isInt != c.IsInt {
			t.Errorf("NumifyTyped(%q) = %q (integer %v), Perl %q (integer %v)", c.In, got, isInt, c.Out, c.IsInt)
		}
		if got := LooksLikeNumber(c.In); got != c.LLN {
			t.Errorf("LooksLikeNumber(%q) = %v, Perl %v", c.In, got, c.LLN)
		}
		if got := True(c.In); got != c.True {
			t.Errorf("True(%q) = %v, Perl %v", c.In, got, c.True)
		}
	}
}

// TestText checks lc and substr
func TestText(t *testing.T) {
	for _, c := range loadGolden(t).Text {
		if got := Lc(c.In); got != c.Lc {
			t.Errorf("Lc(%q) = %q, Perl %q", c.In, got, c.Lc)
		}
		if got := Substr(c.In, 128); got != c.Substr128 {
			t.Errorf("Substr(%q, 128) = %q, Perl %q", c.In, got, c.Substr128)
		}
		if got := Substr(c.In, 3); got != c.Substr3 {
			t.Errorf("Substr(%q, 3) = %q, Perl %q", c.In, got, c.Substr3)
		}
	}
}

// TestRound checks Math::Round round and int()
func TestRound(t *testing.T) {
	for _, c := range loadGolden(t).Round {
		f := fromBits(t, c.Bits)
		if got := NumString(RoundHalfAway(f)); got != c.Round {
			t.Errorf("RoundHalfAway(%v) = %q, Perl %q", f, got, c.Round)
		}
		// int() gives an integer (IV) when it fits
		got := NumString(Int(f))
		if i := Int(f); math.Abs(i) < 1<<63 {
			got = strconv.FormatInt(int64(i), 10)
		}
		if got != c.Int {
			t.Errorf("Int(%v) = %q, Perl %q", f, got, c.Int)
		}
	}
}

// TestSprintfFixed checks sprintf("%.Nf")
func TestSprintfFixed(t *testing.T) {
	for _, c := range loadGolden(t).Fixed {
		f := fromBits(t, c.Bits)
		for places, want := range c.Out {
			n, _ := strconv.Atoi(places)
			if got := SprintfFixed(f, n); got != want {
				t.Errorf("SprintfFixed(%v, %d) = %q, Perl %q", f, n, got, want)
			}
		}
	}
}
